window.docContents[67].resolve({"/2___-Basic-notions-of-representation-theory/2___8___-Quivers/Notation-for-vertices-and-edges-of-quivers/#Chapter2___Discussion_quiver_notation":{"contents":"We denote the set of vertices of the quiver Q as I and the set of edges as E. For an edge h \\in E, let h', h'' denote the source and target of h, respectively:\n\n\\bullet_{h'} \\xrightarrow{h} \\bullet_{h''}\n\n\n\n","context":"Introduction to Representation Theory\t2. Basic notions of representation theory\t2.8. Quivers\tNotation for vertices and edges of quivers","header":"Notation for vertices and edges of quivers","id":"/2___-Basic-notions-of-representation-theory/2___8___-Quivers/Notation-for-vertices-and-edges-of-quivers/#Chapter2___Discussion_quiver_notation"},"/2___-Basic-notions-of-representation-theory/2___3___-Representations/Schur___s-lemma-for-algebraically-closed-fields/#Chapter2___Corollary2___3___10":{"contents":"Corollary 2.3.10 (Schur's lemma for algebraically closed fields). Let V be a finite dimensional irreducible representation of an algebra A over an algebraically closed field k, and let \\phi : V \\to V be an intertwining operator. Then \\phi = \\lambda \\cdot \\operatorname{Id} for some \\lambda \\in k (a scalar operator).\n\n\n\n","context":"Introduction to Representation Theory\t2. Basic notions of representation theory\t2.3. Representations\tSchur's lemma for algebraically closed fields","header":"Schur's lemma for algebraically closed fields","id":"/2___-Basic-notions-of-representation-theory/2___3___-Representations/Schur___s-lemma-for-algebraically-closed-fields/#Chapter2___Corollary2___3___10"},"/5___-Representations-of-finite-groups___-Further-results/5___6___-Representations-of-products/Irreducible-representations-of-G-x-H-are-tensor-products-V_i-___-W_j/#Chapter5___Theorem5___6___1":{"contents":"Theorem 5.6.1. Let G, H be finite groups, let \\{V_i\\} be the irreducible representations of G over a field k (of any characteristic), and let \\{W_j\\} be the irreducible representations of H over k. Then the irreducible representations of G \\times H over k are \\{V_i \\otimes W_j\\}.\n\nProof. This follows from Theorem 3.10.2. \\square\n\n\n\n","context":"Introduction to Representation Theory\t5. Representations of finite groups: Further results\t5.6. Representations of products\tIrreducible representations of G x H are tensor products V_i ⊗ W_j","header":"Irreducible representations of G x H are tensor products V_i ⊗ W_j","id":"/5___-Representations-of-finite-groups___-Further-results/5___6___-Representations-of-products/Irreducible-representations-of-G-x-H-are-tensor-products-V_i-___-W_j/#Chapter5___Theorem5___6___1"},"/5___-Representations-of-finite-groups___-Further-results/5___2___-Algebraic-numbers-and-algebraic-integers/Algebraic-integers-intersect-rationals-in-the-integers/#Chapter5___Proposition5___2___5":{"contents":"Proposition 5.2.5. \\overline{\\mathbb{Z}} \\cap \\mathbb{Q} = \\mathbb{Z}.\n\nProof. We will be using Definition 5.2.1. Let z be a root of\n\np(x) = x^n + a_1 x^{n-1} + \\ldots + a_{n-1} x + a_n,\n\nand suppose\n\nz = \\frac{p}{q} \\in \\mathbb{Q}, \\quad \\gcd(p, q) = 1.\n\nNotice that the leading term of p(z) will have q^n in the denominator, whereas all the other terms will have a lower power of q there. Thus, if q \\neq \\pm 1, then p(z) \\notin \\mathbb{Z}, a contradiction. Thus, z \\in \\overline{\\mathbb{Z}} \\cap \\mathbb{Q} \\Rightarrow z \\in \\mathbb{Z}. The reverse inclusion follows because n \\in \\mathbb{Z} is a root of x - n. \\square\n\n\n\n","context":"Introduction to Representation Theory\t5. Representations of finite groups: Further results\t5.2. Algebraic numbers and algebraic integers\tAlgebraic integers intersect rationals in the integers","header":"Algebraic integers intersect rationals in the integers","id":"/5___-Representations-of-finite-groups___-Further-results/5___2___-Algebraic-numbers-and-algebraic-integers/Algebraic-integers-intersect-rationals-in-the-integers/#Chapter5___Proposition5___2___5"}});
